from __future__ import annotations

import httpx


class MeridianClient:
    """HTTP client for the Meridian payments API."""

    def __init__(self, base_url: str, api_key: str) -> None:
        self._client = httpx.Client(
            base_url=base_url.rstrip("/"),
            headers={"Authorization": f"Bearer {api_key}"},
        )

    def fetch_all_payments(self) -> list[dict]:
        resp = self._client.get("/payments")
        resp.raise_for_status()
        return resp.json()

    def total_count(self) -> int:
        resp = self._client.get("/payments/count")
        resp.raise_for_status()
        return resp.json()

    def create_payment(self, amount_minor: int, currency: str, idempotency_key: str) -> str:
        resp = self._client.post(
            "/payments",
            json={"amount": amount_minor, "currency": currency},
            headers={"Idempotency-Key": idempotency_key},
        )
        resp.raise_for_status()
        return resp.json()["id"]

from __future__ import annotations

import json
import sqlite3


class Store:
    """SQLite-backed payment persistence with upsert semantics and sync tracking."""

    def __init__(self, path: str) -> None:
        self._conn = sqlite3.connect(path)
        self._conn.row_factory = sqlite3.Row
        self._ensure_schema()

    def _ensure_schema(self) -> None:
        self._conn.execute(
            """
            CREATE TABLE IF NOT EXISTS payments (
                id TEXT PRIMARY KEY,
                amount INTEGER,
                currency TEXT,
                created_at TEXT,
                data TEXT
            )
            """
        )
        self._conn.execute(
            """
            CREATE TABLE IF NOT EXISTS metadata (
                key TEXT PRIMARY KEY,
                value TEXT
            )
            """
        )
        self._conn.commit()

    def upsert_many(self, payments: list[dict]) -> int:
        if not payments:
            return 0

        existing = {row["id"] for row in self._conn.execute("SELECT id FROM payments")}
        new_count = sum(1 for p in payments if p.get("id") not in existing)

        for p in payments:
            self._conn.execute(
                """
                INSERT OR REPLACE INTO payments (id, amount, currency, created_at, data)
                VALUES (?, ?, ?, ?, ?)
                """,
                (
                    p.get("id"),
                    p.get("amount"),
                    p.get("currency"),
                    p.get("created_at"),
                    json.dumps(p),
                ),
            )

        self._conn.commit()
        return new_count

    def all_payments(self) -> list[dict]:
        rows = self._conn.execute(
            "SELECT id, amount, currency, created_at, data FROM payments ORDER BY created_at ASC"
        ).fetchall()

        result = []
        for row in rows:
            d = json.loads(row["data"]) if row["data"] else {}
            if row["id"] is not None:
                d["id"] = row["id"]
            if row["amount"] is not None:
                d["amount"] = row["amount"]
            if row["currency"] is not None:
                d["currency"] = row["currency"]
            if row["created_at"] is not None:
                d["created_at"] = row["created_at"]
            result.append(d)

        return result

    def count(self) -> int:
        row = self._conn.execute("SELECT COUNT(*) AS cnt FROM payments").fetchone()
        return row["cnt"]

    def last_sync(self) -> str | None:
        row = self._conn.execute(
            "SELECT value FROM metadata WHERE key = 'last_sync'"
        ).fetchone()
        return row["value"] if row else None

    def set_last_sync(self, when: str) -> None:
        self._conn.execute(
            "INSERT OR REPLACE INTO metadata (key, value) VALUES ('last_sync', ?)",
            (when,),
        )
        self._conn.commit()

from __future__ import annotations

import json
import os
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs

from .meridian import MeridianClient
from .store import Store


def _read_index() -> bytes:
    """Read the bundled index.html from the package."""
    path = os.path.join(os.path.dirname(__file__), "web", "index.html")
    with open(path, "rb") as f:
        return f.read()


class _Handler(BaseHTTPRequestHandler):
    """HTTP handler for the vendor sync API and static frontend."""

    # Injected by serve()
    store: Store
    client: MeridianClient

    def log_message(self, format, *args) -> None:
        pass  # silence default stderr logging

    # ---- routing --------------------------------------------------------

    def do_GET(self) -> None:
        parsed = urlparse(self.path)
        path = parsed.path.rstrip("/") or "/"

        if path == "/":
            self._send_index()
        elif path == "/api/health":
            self._health()
        elif path == "/api/payments":
            self._payments(parse_qs(parsed.query))
        elif path == "/api/summary":
            self._summary()
        else:
            self._json(404, {"error": "not_found"})

    def do_POST(self) -> None:
        parsed = urlparse(self.path)
        path = parsed.path.rstrip("/") or "/"

        if path == "/api/sync":
            self._sync()
        else:
            self._json(404, {"error": "not_found"})

    # ---- handlers -------------------------------------------------------

    def _send_index(self) -> None:
        body = _read_index()
        self.send_response(200)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _health(self) -> None:
        self._json(200, {
            "status": "ok",
            "payments": self.store.count(),
            "last_sync": self.store.last_sync(),
        })

    def _payments(self, qs: dict[str, list[str]]) -> None:
        # Parse & validate limit
        raw_limit = qs.get("limit", ["25"])[0]
        try:
            limit = int(raw_limit)
        except (ValueError, TypeError):
            return self._json(400, {"error": "bad_request"})
        if limit < 0:
            return self._json(400, {"error": "bad_request"})
        if limit > 100:
            limit = 100

        # Parse & validate offset
        raw_offset = qs.get("offset", ["0"])[0]
        try:
            offset = int(raw_offset)
        except (ValueError, TypeError):
            return self._json(400, {"error": "bad_request"})
        if offset < 0:
            return self._json(400, {"error": "bad_request"})

        payments = self.store.all_payments()
        total = len(payments)
        page = payments[offset : offset + limit]

        data = [
            {
                "id": p["id"],
                "amount_minor": p["amount"],
                "currency": p["currency"],
                "created_at": p["created_at"],
                "status": p.get("status", "completed"),
            }
            for p in page
        ]

        self._json(200, {"data": data, "total": total, "limit": limit, "offset": offset})

    def _summary(self) -> None:
        payments = self.store.all_payments()
        count = len(payments)

        if count == 0:
            return self._json(200, {
                "count": 0,
                "total_minor": 0,
                "average_minor": 0,
            })

        total_minor = sum(p["amount"] for p in payments)
        average_minor = total_minor // count

        self._json(200, {
            "count": count,
            "total_minor": total_minor,
            "average_minor": average_minor,
        })

    def _sync(self) -> None:
        try:
            payments = self.client.fetch_all_payments()
            new_count = self.store.upsert_many(payments)
            total = self.store.count()
            from datetime import datetime, timezone
            self.store.set_last_sync(datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"))
            self._json(200, {"new": new_count, "total": total})
        except Exception as e:
            self._json(500, {"error": str(e)})

    # ---- helpers --------------------------------------------------------

    def _json(self, status: int, body: dict) -> None:
        raw = json.dumps(body).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(raw)))
        self.end_headers()
        self.wfile.write(raw)


def serve(port: int, store: Store, client: MeridianClient) -> None:
    """Start the JSON API and static frontend server on 127.0.0.1:port."""
    _Handler.store = store
    _Handler.client = client
    httpd = HTTPServer(("127.0.0.1", port), _Handler)
    print(f"Serving on 127.0.0.1:{port}")
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        httpd.server_close()

